// Python-flavored JSON value utilities: type checks and deep equality
// matching the semantics of the Python `jsonschema` library.

export function isObject(x) {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

export function isArray(x) {
  return Array.isArray(x);
}

// String length in Unicode code points (Python's len()).
export function codePointLength(s) {
  return [...s].length;
}

// Python jsonschema type checking. `allowAny` enables the draft-03 "any" type.
// Unknown type names throw (mirrors jsonschema's UnknownType -> crash, exit 1).
export function checkType(instance, type, allowAny = false) {
  switch (type) {
    case 'null':
      return instance === null;
    case 'boolean':
      return instance === true || instance === false;
    case 'object':
      return isObject(instance);
    case 'array':
      return Array.isArray(instance);
    case 'number':
      return typeof instance === 'number';
    case 'integer':
      return typeof instance === 'number' && Number.isInteger(instance);
    case 'string':
      return typeof instance === 'string';
    case 'any':
      if (allowAny) return true;
      throw new Error(`Unknown type: ${type}`);
    default:
      throw new Error(`Unknown type: ${type}`);
  }
}

// Deep equality matching observed jsonschema behavior: booleans are always
// distinct from numbers (recursively), numeric values compare by value
// (1 == 1.0), objects ignore key order.
export function deepEqual(a, b) {
  const ta = typeof a;
  const tb = typeof b;
  if (ta !== tb) return false;
  if (ta !== 'object') return a === b; // number, string, boolean
  if (a === null || b === null) return a === b;
  const aArr = Array.isArray(a);
  const bArr = Array.isArray(b);
  if (aArr !== bArr) return false;
  if (aArr) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!(k in b) || !deepEqual(a[k], b[k])) return false;
  }
  return true;
}

// JSON-pointer $ref resolution (local refs only).

// Unescape a single JSON-pointer segment: ~1 -> /, then ~0 -> ~.
export function unescapeSegment(segment) {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

// Resolve a local reference like "#", "#/definitions/name" or "#/$defs/x"
// against the root schema. Throws on anything unresolvable (mirrors the
// reference executable crashing with exit code 1).
export function resolveLocalRef(root, ref) {
  if (typeof ref !== 'string') {
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  if (!ref.startsWith('#')) {
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  let fragment = ref.slice(1);
  if (fragment === '') return root;
  try {
    fragment = decodeURIComponent(fragment);
  } catch {
    // keep the raw fragment
  }
  if (!fragment.startsWith('/')) {
    // plain-name fragments / anchors are unsupported
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  const segments = fragment.slice(1).split('/').map(unescapeSegment);
  let current = root;
  for (const seg of segments) {
    if (Array.isArray(current)) {
      if (!/^\d+$/.test(seg)) throw new Error(`Unresolvable reference: ${ref}`);
      const idx = Number(seg);
      if (idx >= current.length) throw new Error(`Unresolvable reference: ${ref}`);
      current = current[idx];
    } else if (typeof current === 'object' && current !== null) {
      if (!(seg in current)) throw new Error(`Unresolvable reference: ${ref}`);
      current = current[seg];
    } else {
      throw new Error(`Unresolvable reference: ${ref}`);
    }
  }
  return current;
}

// Validator core: iterErrors/isValid, keyword dispatch, $ref resolution and
// evaluated-properties/items annotation tracking for unevaluated* keywords.

import { isObject } from './jsonvalues.mjs';
import { resolveLocalRef } from './pointer.mjs';

// Marker object for a single yielded validation error (only counts matter).
const ERROR = Object.freeze({});

export class Validator {
  // config: { keywords: Map<string, handler>, refExclusive: boolean }
  constructor(rootSchema, config) {
    this.root = rootSchema;
    this.config = config;
  }

  isValid(instance, schema = this.root) {
    for (const _ of this.iterErrors(instance, schema)) return false;
    return true;
  }

  countErrors(instance, schema = this.root) {
    let n = 0;
    for (const _ of this.iterErrors(instance, schema)) n++;
    return n;
  }

  *iterErrors(instance, schema) {
    if (schema === true) return;
    if (schema === false) {
      yield ERROR;
      return;
    }
    if (!isObject(schema)) {
      // Python crashes (AttributeError) on non-object schemas
      throw new Error('Schema is not an object');
    }
    // Drafts <= 7 ignore sibling keywords when $ref is present.
    if (this.config.refExclusive && schema.$ref !== undefined) {
      const handler = this.config.keywords.get('$ref');
      yield* handler(this, schema.$ref, instance, schema);
      return;
    }
    for (const [key, handler] of this.config.keywords) {
      if (key in schema) {
        yield* handler(this, schema[key], instance, schema);
      }
    }
  }

  resolveRef(ref) {
    return resolveLocalRef(this.root, ref);
  }

  // --- evaluated annotation tracking (2019-09 / 2020-12) ---

  findEvaluatedProps(instance, schema) {
    const evaluated = new Set();
    const walk = (sch) => {
      if (!isObject(sch)) return;
      if (typeof sch.$ref === 'string') walk(this.resolveRef(sch.$ref));
      if (isObject(sch.properties)) {
        for (const k of Object.keys(sch.properties)) {
          if (k in instance) evaluated.add(k);
        }
      }
      if (isObject(sch.patternProperties)) {
        for (const pat of Object.keys(sch.patternProperties)) {
          const re = new RegExp(pat, 'u');
          for (const k of Object.keys(instance)) {
            if (re.test(k)) evaluated.add(k);
          }
        }
      }
      if ('additionalProperties' in sch) {
        const props = isObject(sch.properties) ? Object.keys(sch.properties) : [];
        const patterns = isObject(sch.patternProperties)
          ? Object.keys(sch.patternProperties).map((p) => new RegExp(p, 'u'))
          : [];
        for (const k of Object.keys(instance)) {
          if (props.includes(k)) continue;
          if (patterns.some((re) => re.test(k))) continue;
          evaluated.add(k);
        }
      }
      for (const kw of ['allOf', 'anyOf', 'oneOf']) {
        if (Array.isArray(sch[kw])) {
          for (const sub of sch[kw]) {
            if (this.isValid(instance, sub)) walk(sub);
          }
        }
      }
      if ('if' in sch) {
        if (this.isValid(instance, sch.if)) {
          walk(sch.if);
          if ('then' in sch) walk(sch.then);
        } else if ('else' in sch) {
          walk(sch.else);
        }
      }
    };
    walk(schema);
    return evaluated;
  }

  findEvaluatedIndexes(instance, schema) {
    const evaluated = new Set();
    const addRange = (from, to) => {
      for (let i = from; i < to; i++) evaluated.add(i);
    };
    const walk = (sch) => {
      if (!isObject(sch)) return;
      if (typeof sch.$ref === 'string') walk(this.resolveRef(sch.$ref));
      if ('items' in sch) {
        if (isObject(sch.items) || typeof sch.items === 'boolean') {
          // schema form: every index is evaluated
          addRange(0, instance.length);
        } else if (Array.isArray(sch.items)) {
          addRange(0, Math.min(sch.items.length, instance.length));
          if (isObject(sch.additionalItems) || typeof sch.additionalItems === 'boolean') {
            addRange(sch.items.length, instance.length);
          }
        }
      }
      if (Array.isArray(sch.prefixItems)) {
        addRange(0, Math.min(sch.prefixItems.length, instance.length));
        if ('items' in sch) addRange(sch.prefixItems.length, instance.length);
      }
      if ('contains' in sch) {
        for (let i = 0; i < instance.length; i++) {
          if (this.isValid(instance[i], sch.contains)) evaluated.add(i);
        }
      }
      for (const kw of ['allOf', 'anyOf', 'oneOf']) {
        if (Array.isArray(sch[kw])) {
          for (const sub of sch[kw]) {
            if (this.isValid(instance, sub)) walk(sub);
          }
        }
      }
      if ('if' in sch) {
        if (this.isValid(instance, sch.if)) {
          walk(sch.if);
          if ('then' in sch) walk(sch.then);
        } else if ('else' in sch) {
          walk(sch.else);
        }
      }
    };
    walk(schema);
    return evaluated;
  }
}

export { ERROR };

// Keyword handler implementations. Each handler is a generator with the
// signature (validator, keywordValue, instance, schema) yielding one marker
// per validation error. Anything that crashes the Python reference
// (unknown types, multipleOf 0, bad regexes, ...) throws here, which the
// entry point turns into exit code 1.

import {
  isObject,
  checkType,
  deepEqual,
  codePointLength,
} from './jsonvalues.mjs';
import { ERROR } from './engine.mjs';

const ensureList = (x) => (Array.isArray(x) ? x : [x]);

// --- generic ---

export function* typeNormal(v, types, instance) {
  for (const t of ensureList(types)) {
    if (checkType(instance, t)) return;
  }
  yield ERROR;
}

export function* enumK(v, enums, instance) {
  for (const e of ensureList(enums)) {
    if (deepEqual(instance, e)) return;
  }
  yield ERROR;
}

export function* constK(v, c, instance) {
  if (!deepEqual(instance, c)) yield ERROR;
}

export function* multipleOf(v, dB, instance) {
  if (typeof instance !== 'number') return;
  if (dB === 0) throw new Error('ZeroDivisionError');
  let failed;
  if (Number.isInteger(dB)) {
    failed = instance % dB !== 0;
  } else {
    const quotient = instance / dB;
    failed = Math.trunc(quotient) !== quotient;
  }
  if (failed) yield ERROR;
}

// --- numeric range ---

export function* maximum(v, maximum, instance) {
  if (typeof instance !== 'number') return;
  if (instance > maximum) yield ERROR;
}

export function* minimum(v, minimum, instance) {
  if (typeof instance !== 'number') return;
  if (instance < minimum) yield ERROR;
}

// Draft 3/4: exclusiveMinimum/Maximum are boolean modifiers of minimum/maximum.
export function* maximumLegacy(v, maximum, instance, schema) {
  if (typeof instance !== 'number') return;
  const exclusive = schema.exclusiveMaximum;
  if (exclusive ? instance >= maximum : instance > maximum) yield ERROR;
}

export function* minimumLegacy(v, minimum, instance, schema) {
  if (typeof instance !== 'number') return;
  const exclusive = schema.exclusiveMinimum;
  if (exclusive ? instance <= minimum : instance < minimum) yield ERROR;
}

// Draft 6+: standalone numeric keywords. Booleans compare as 1/0 (Python).
const numericOperand = (x) => (x === true ? 1 : x === false ? 0 : x);

export function* exclusiveMaximum(v, eM, instance) {
  if (typeof instance !== 'number') return;
  const m = numericOperand(eM);
  if (typeof m !== 'number') throw new Error('TypeError: not comparable');
  if (instance >= m) yield ERROR;
}

export function* exclusiveMinimum(v, eM, instance) {
  if (typeof instance !== 'number') return;
  const m = numericOperand(eM);
  if (typeof m !== 'number') throw new Error('TypeError: not comparable');
  if (instance <= m) yield ERROR;
}

// --- strings ---

export function* maxLength(v, max, instance) {
  if (typeof instance !== 'string') return;
  if (codePointLength(instance) > max) yield ERROR;
}

export function* minLength(v, min, instance) {
  if (typeof instance !== 'string') return;
  if (codePointLength(instance) < min) yield ERROR;
}

export function* pattern(v, pat, instance) {
  if (typeof instance !== 'string') return;
  if (!new RegExp(pat, 'u').test(instance)) yield ERROR;
}

// --- arrays ---

export function* maxItems(v, max, instance) {
  if (!Array.isArray(instance)) return;
  if (instance.length > max) yield ERROR;
}

export function* minItems(v, min, instance) {
  if (!Array.isArray(instance)) return;
  if (instance.length < min) yield ERROR;
}

export function* uniqueItems(v, uI, instance) {
  if (!uI || !Array.isArray(instance)) return;
  for (let i = 0; i < instance.length; i++) {
    for (let j = i + 1; j < instance.length; j++) {
      if (deepEqual(instance[i], instance[j])) {
        yield ERROR;
        return;
      }
    }
  }
}

// items for drafts 3 .. 2019-09: schema form or array (tuple) form.
export function* itemsLegacy(v, items, instance, schema) {
  if (!Array.isArray(instance)) return;
  if (isObject(items) || typeof items === 'boolean') {
    for (const item of instance) {
      yield* v.iterErrors(item, items);
    }
  } else {
    const n = Math.min(items.length, instance.length);
    for (let i = 0; i < n; i++) {
      yield* v.iterErrors(instance[i], items[i]);
    }
  }
}

export function* additionalItems(v, aI, instance, schema) {
  if (!Array.isArray(instance)) return;
  const items = 'items' in schema ? schema.items : {};
  if (isObject(items)) return;
  const lenItems = Array.isArray(items) ? items.length : items.length; // crash on non-array like Python len()
  if (isObject(aI) || typeof aI === 'boolean') {
    if (aI === false) {
      if (instance.length > lenItems) yield ERROR;
    } else {
      for (let i = lenItems; i < instance.length; i++) {
        yield* v.iterErrors(instance[i], aI);
      }
    }
  } else if (!aI) {
    if (instance.length > lenItems) yield ERROR;
  }
}

// 2020-12: prefixItems (tuple) + items (schema for the rest; array form crashes).
export function* prefixItems(v, prefixItems, instance) {
  if (!Array.isArray(instance)) return;
  const n = Math.min(prefixItems.length, instance.length);
  for (let i = 0; i < n; i++) {
    yield* v.iterErrors(instance[i], prefixItems[i]);
  }
}

export function* items2020(v, items, instance, schema) {
  if (!Array.isArray(instance)) return;
  if (Array.isArray(items)) {
    // Python crashes on array-form items in 2020-12
    throw new Error('AttributeError: list has no items()');
  }
  const start = Array.isArray(schema.prefixItems) ? schema.prefixItems.length : 0;
  for (let i = start; i < instance.length; i++) {
    yield* v.iterErrors(instance[i], items);
  }
}

export function* contains(v, c, instance, schema) {
  if (!Array.isArray(instance)) return;
  let matches = 0;
  for (const item of instance) {
    if (v.isValid(item, c)) matches++;
  }
  const minContains = schema.minContains !== undefined ? schema.minContains : 1;
  const maxContains = schema.maxContains !== undefined ? schema.maxContains : Infinity;
  if (matches > maxContains) {
    yield ERROR;
  } else if (matches < minContains) {
    yield ERROR;
  }
}

// --- objects ---

export function* maxProperties(v, max, instance) {
  if (!isObject(instance)) return;
  if (Object.keys(instance).length > max) yield ERROR;
}

export function* minProperties(v, min, instance) {
  if (!isObject(instance)) return;
  if (Object.keys(instance).length < min) yield ERROR;
}

const iterateRequired = (required) => {
  if (Array.isArray(required)) return required;
  if (typeof required === 'string') return [...required]; // Python iterates chars
  throw new Error('TypeError: not iterable');
};

export function* required(v, req, instance) {
  if (!isObject(instance)) return;
  for (const property of iterateRequired(req)) {
    if (!(property in instance)) yield ERROR;
  }
}

export function* properties(v, properties, instance) {
  if (!isObject(instance)) return;
  if (!isObject(properties)) return;
  for (const [property, subschema] of Object.entries(properties)) {
    if (property in instance) {
      yield* v.iterErrors(instance[property], subschema);
    }
  }
}

// Draft 3: `required` is a boolean inside each property subschema.
export function* propertiesDraft3(v, properties, instance) {
  if (!isObject(instance)) return;
  if (!isObject(properties)) return;
  for (const [property, subschema] of Object.entries(properties)) {
    if (property in instance) {
      yield* v.iterErrors(instance[property], subschema);
    } else if (isObject(subschema) && subschema.required) {
      yield ERROR;
    }
  }
}

export function* patternProperties(v, patternProperties, instance) {
  if (!isObject(instance)) return;
  if (!isObject(patternProperties)) return;
  for (const [pat, subschema] of Object.entries(patternProperties)) {
    const re = new RegExp(pat, 'u');
    for (const [property, value] of Object.entries(instance)) {
      if (re.test(property)) {
        yield* v.iterErrors(value, subschema);
      }
    }
  }
}

export function* additionalProperties(v, aP, instance, schema) {
  if (!isObject(instance)) return;
  const props = isObject(schema.properties) ? Object.keys(schema.properties) : [];
  const patterns = isObject(schema.patternProperties)
    ? Object.keys(schema.patternProperties).map((p) => new RegExp(p, 'u'))
    : [];
  const extras = Object.keys(instance).filter(
    (k) => !props.includes(k) && !patterns.some((re) => re.test(k)),
  );
  if (isObject(aP)) {
    for (const extra of extras) {
      yield* v.iterErrors(instance[extra], aP);
    }
  } else if (!aP) {
    if (extras.length) yield ERROR;
  }
}

export function* propertyNames(v, pN, instance) {
  if (!isObject(instance)) return;
  for (const property of Object.keys(instance)) {
    yield* v.iterErrors(property, pN);
  }
}

// dependencies: drafts 3-7.
export function* dependencies(v, dependencies, instance) {
  if (!isObject(instance)) return;
  if (!isObject(dependencies)) return;
  for (const [property, dependency] of Object.entries(dependencies)) {
    if (!(property in instance)) continue;
    if (Array.isArray(dependency)) {
      for (const dep of dependency) {
        if (!(dep in instance)) yield ERROR;
      }
    } else {
      yield* v.iterErrors(instance, dependency);
    }
  }
}

// 2019-09+.
export function* dependentRequired(v, dependentRequired, instance) {
  if (!isObject(instance)) return;
  if (!isObject(dependentRequired)) return;
  for (const [property, deps] of Object.entries(dependentRequired)) {
    if (!(property in instance)) continue;
    for (const dep of deps) {
      if (!(dep in instance)) yield ERROR;
    }
  }
}

export function* dependentSchemas(v, dependentSchemas, instance) {
  if (!isObject(instance)) return;
  if (!isObject(dependentSchemas)) return;
  for (const [property, subschema] of Object.entries(dependentSchemas)) {
    if (!(property in instance)) continue;
    yield* v.iterErrors(instance, subschema);
  }
}

// --- applicators ---

export function* allOf(v, allOf, instance) {
  for (const subschema of allOf) {
    yield* v.iterErrors(instance, subschema);
  }
}

export function* anyOf(v, anyOf, instance) {
  for (const subschema of anyOf) {
    if (v.isValid(instance, subschema)) return;
  }
  yield ERROR;
}

export function* oneOf(v, oneOf, instance) {
  let matches = 0;
  for (const subschema of oneOf) {
    if (v.isValid(instance, subschema)) matches++;
  }
  if (matches !== 1) yield ERROR;
}

export function* notK(v, notSchema, instance) {
  if (v.isValid(instance, notSchema)) yield ERROR;
}

export function* ifK(v, ifSchema, instance, schema) {
  if (v.isValid(instance, ifSchema)) {
    if ('then' in schema) yield* v.iterErrors(instance, schema.then);
  } else {
    if ('else' in schema) yield* v.iterErrors(instance, schema.else);
  }
}

export function* ref(v, refValue, instance) {
  yield* v.iterErrors(instance, v.resolveRef(refValue));
}

// --- unevaluated* (2019-09+) ---
// Observed reference behavior: a single error when at least one unevaluated
// property/item fails the given schema (or exists, for `false`).

export function* unevaluatedProperties(v, uP, instance, schema) {
  if (!isObject(instance)) return;
  const evaluated = v.findEvaluatedProps(instance, schema);
  const unevaluated = Object.keys(instance).filter((k) => !evaluated.has(k));
  if (!unevaluated.length) return;
  if (uP === false) {
    yield ERROR;
    return;
  }
  for (const k of unevaluated) {
    if (!v.isValid(instance[k], uP)) {
      yield ERROR;
      return;
    }
  }
}

export function* unevaluatedItems(v, uI, instance, schema) {
  if (!Array.isArray(instance)) return;
  const evaluated = v.findEvaluatedIndexes(instance, schema);
  const unevaluated = [];
  for (let i = 0; i < instance.length; i++) {
    if (!evaluated.has(i)) unevaluated.push(i);
  }
  if (!unevaluated.length) return;
  if (uI === false) {
    yield ERROR;
    return;
  }
  for (const i of unevaluated) {
    if (!v.isValid(instance[i], uI)) {
      yield ERROR;
      return;
    }
  }
}

// --- draft 3 specifics ---

export function* typeDraft3(v, types, instance) {
  for (const t of ensureList(types)) {
    if (isObject(t)) {
      if (v.isValid(instance, t)) return;
    } else if (checkType(instance, t, true)) {
      return;
    }
  }
  yield ERROR;
}

export function* disallow(v, disallow, instance) {
  for (const d of ensureList(disallow)) {
    if (isObject(d)) {
      if (v.isValid(instance, d)) yield ERROR;
    } else if (checkType(instance, d, true)) {
      yield ERROR;
    }
  }
}

export function* extendsK(v, ext, instance) {
  for (const subschema of ensureList(ext)) {
    yield* v.iterErrors(instance, subschema);
  }
}

