// The six validator class configs plus `validator_for` ($schema mapping).

import { Validator } from './engine.mjs';
import * as K from './keywords.mjs';

const makeConfig = (entries, refExclusive) => ({
  keywords: new Map(entries.filter(([, h]) => h)),
  refExclusive,
});

const common = {
  additionalProperties: K.additionalProperties,
  enum: K.enumK,
  items: K.itemsLegacy,
  maxItems: K.maxItems,
  maxLength: K.maxLength,
  maxProperties: K.maxProperties,
  minItems: K.minItems,
  minLength: K.minLength,
  minProperties: K.minProperties,
  pattern: K.pattern,
  patternProperties: K.patternProperties,
  uniqueItems: K.uniqueItems,
  $ref: K.ref,
};

const applicators = {
  allOf: K.allOf,
  anyOf: K.anyOf,
  not: K.notK,
  oneOf: K.oneOf,
};

const toEntries = (obj) => Object.entries(obj);

const draft3 = makeConfig(
  toEntries({
    ...common,
    additionalItems: K.additionalItems,
    dependencies: K.dependencies,
    disallow: K.disallow,
    divisibleBy: K.multipleOf,
    extends: K.extendsK,
    maximum: K.maximumLegacy,
    minimum: K.minimumLegacy,
    properties: K.propertiesDraft3,
    type: K.typeDraft3,
  }),
  true,
);

const draft4 = makeConfig(
  toEntries({
    ...common,
    ...applicators,
    additionalItems: K.additionalItems,
    dependencies: K.dependencies,
    maximum: K.maximumLegacy,
    minimum: K.minimumLegacy,
    multipleOf: K.multipleOf,
    properties: K.properties,
    required: K.required,
    type: K.typeNormal,
  }),
  true,
);

const draft6 = makeConfig(
  toEntries({
    ...common,
    ...applicators,
    additionalItems: K.additionalItems,
    const: K.constK,
    contains: K.contains,
    dependencies: K.dependencies,
    exclusiveMaximum: K.exclusiveMaximum,
    exclusiveMinimum: K.exclusiveMinimum,
    maximum: K.maximum,
    minimum: K.minimum,
    multipleOf: K.multipleOf,
    properties: K.properties,
    propertyNames: K.propertyNames,
    required: K.required,
    type: K.typeNormal,
  }),
  true,
);

const draft7 = makeConfig(
  toEntries([...draft6.keywords, ['if', K.ifK]]),
  true,
);

const draft201909 = makeConfig(
  toEntries([
    ...draft7.keywords,
    ['$recursiveRef', K.ref],
    ['dependentRequired', K.dependentRequired],
    ['dependentSchemas', K.dependentSchemas],
    ['unevaluatedItems', K.unevaluatedItems],
    ['unevaluatedProperties', K.unevaluatedProperties],
  ].filter(([k]) => k !== 'dependencies')),
  false,
);

const draft202012 = makeConfig(
  toEntries([
    ...draft201909.keywords,
    ['$dynamicRef', K.ref],
    ['prefixItems', K.prefixItems],
    ['items', K.items2020],
  ].filter(([k]) => k !== 'additionalItems' && k !== '$recursiveRef')),
  false,
);

const DRAFTS = [
  ['http://json-schema.org/draft-03/schema#', 'Draft3Validator', draft3],
  ['http://json-schema.org/draft-04/schema#', 'Draft4Validator', draft4],
  ['http://json-schema.org/draft-06/schema#', 'Draft6Validator', draft6],
  ['http://json-schema.org/draft-07/schema#', 'Draft7Validator', draft7],
  ['https://json-schema.org/draft/2019-09/schema', 'Draft201909Validator', draft201909],
  ['https://json-schema.org/draft/2020-12/schema', 'Draft202012Validator', draft202012],
];

const LATEST = DRAFTS[DRAFTS.length - 1];

const DEPRECATION_WARNING =
  'test13.py:15: DeprecationWarning: The metaschema specified by $schema ' +
  'was not found. Using the latest draft to validate, but this will raise ' +
  'an error in the future.';

// Mirrors jsonschema.validators.validator_for with default=_LATEST_VERSION.
export function validatorFor(schema) {
  let pick = LATEST;
  if (schema === true || schema === false) {
    // boolean schema -> latest, no warning
  } else if (typeof schema !== 'object' || schema === null) {
    // Python crashes with TypeError on `"$schema" not in schema`
    throw new Error("TypeError: argument of type is not iterable");
  } else if (!('$schema' in schema)) {
    // no warning
  } else {
    const uri = schema.$schema;
    const found = DRAFTS.find(([u]) => u === uri);
    if (found) {
      pick = found;
    } else {
      console.error(DEPRECATION_WARNING);
    }
  }
  const [, name, config] = pick;
  return {
    name,
    create: (rootSchema) => new Validator(rootSchema, config),
  };
}

