// argparse-style manual CLI parsing for --a/--b.

import { basename } from 'node:path';

// argparse's negative-number matcher; tokens like -5 or -1.5 are values,
// not options (the parser has no number-like option strings).
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv) {
  const prog = basename(argv[1] || 'test13.mjs');
  const usage = `usage: ${prog} [-h] --a A --b B`;
  const helpText = [
    usage,
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A       instance (JSON string)',
    '  --b B       schema (JSON string)',
  ].join('\n');

  const fail = (message) => {
    console.error(usage);
    console.error(`${prog}: error: ${message}`);
    process.exit(2);
  };

  const values = {};
  const extras = [];
  const args = argv.slice(2);

  for (let i = 0; i < args.length; i++) {
    const token = args[i];
    if (token === '-h' || token === '--help') {
      console.log(helpText);
      process.exit(0);
    }
    let name = token;
    let value;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      value = token.slice(eq + 1);
    }
    if (name === '--a' || name === '--b') {
      if (value === undefined) {
        const next = args[i + 1];
        if (next === undefined || isOptionLike(next)) {
          fail(`argument ${name}: expected one argument`);
        }
        value = next;
        i++;
      }
      values[name] = value;
    } else {
      extras.push(token);
    }
  }

  const missing = [];
  if (!('--a' in values)) missing.push('--a');
  if (!('--b' in values)) missing.push('--b');
  if (missing.length) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: values['--a'], b: values['--b'] };
}

// Entry point: reimplementation of test13.py in pure Node.js ESM.

import { parseArgs } from './lib/argparse.mjs';
import { validatorFor } from './lib/drafts.mjs';

function main() {
  const { a, b } = parseArgs(process.argv);

  let instance;
  let schema;
  try {
    instance = JSON.parse(a);
  } catch (e) {
    console.error(`JSONDecodeError (--a): ${e.message}`);
    process.exit(1);
  }
  try {
    schema = JSON.parse(b);
  } catch (e) {
    console.error(`JSONDecodeError (--b): ${e.message}`);
    process.exit(1);
  }

  const validatorClass = validatorFor(schema);
  const validator = validatorClass.create(schema);

  const result = validator.isValid(instance);
  const errorCount = validator.countErrors(instance);

  console.log(validatorClass.name);
  console.log(result ? 'True' : 'False');
  console.log(errorCount);
}

try {
  main();
} catch (e) {
  // Mirrors the reference crashing with a Python traceback (exit 1):
  // unknown types, multipleOf 0, unresolvable $refs, etc.
  console.error(String((e && e.stack) || e));
  process.exit(1);
}

// Python-flavored JSON parsing.
//
// Python's json.loads distinguishes int from float (1 vs 1.0), and the
// jsonschema draft-03/04 type checkers reject non-int numbers for
// "integer". JS collapses both to `number`, so floats are boxed in a
// PyFloat wrapper to preserve the distinction. Python's json also accepts
// NaN/Infinity/-Infinity.

export class PyFloat {
  constructor(value) {
    this.value = value;
  }
}

export const isPyFloat = (x) => x instanceof PyFloat;

export const isNumeric = (x) => typeof x === 'number' || x instanceof PyFloat;

export const numVal = (x) => (x instanceof PyFloat ? x.value : x);

export function parsePythonJson(text) {
  let i = 0;
  const n = text.length;

  const error = (msg) => {
    throw new Error(`JSONDecodeError: ${msg}`);
  };

  const skipWs = () => {
    while (i < n && (text[i] === ' ' || text[i] === '\t' || text[i] === '\n' || text[i] === '\r')) i++;
  };

  const parseString = () => {
    // assumes text[i] === '"'
    i++;
    let out = '';
    while (i < n) {
      const c = text[i];
      if (c === '"') {
        i++;
        return out;
      }
      if (c === '\\') {
        i++;
        if (i >= n) break;
        const e = text[i];
        switch (e) {
          case '"': out += '"'; i++; break;
          case '\\': out += '\\'; i++; break;
          case '/': out += '/'; i++; break;
          case 'b': out += '\b'; i++; break;
          case 'f': out += '\f'; i++; break;
          case 'n': out += '\n'; i++; break;
          case 'r': out += '\r'; i++; break;
          case 't': out += '\t'; i++; break;
          case 'u': {
            const hex = text.slice(i + 1, i + 5);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) error('Invalid \\uXXXX escape');
            const code = parseInt(hex, 16);
            out += String.fromCharCode(code);
            i += 5;
            break;
          }
          default:
            error(`Invalid \\escape: ${e}`);
        }
      } else if (c < ' ') {
        error('Invalid control character');
      } else {
        out += c;
        i++;
      }
    }
    error('Unterminated string');
  };

  const parseNumber = () => {
    const start = i;
    if (text[i] === '-') i++;
    if (text.startsWith('Infinity', i)) {
      i += 8;
      return new PyFloat(text[start] === '-' ? -Infinity : Infinity);
    }
    if (i >= n || !/[0-9]/.test(text[i])) error('Expecting value');
    if (text[i] === '0') {
      i++;
    } else {
      while (i < n && /[0-9]/.test(text[i])) i++;
    }
    let isFloat = false;
    if (text[i] === '.') {
      isFloat = true;
      i++;
      if (i >= n || !/[0-9]/.test(text[i])) error('Expecting value');
      while (i < n && /[0-9]/.test(text[i])) i++;
    }
    if (text[i] === 'e' || text[i] === 'E') {
      isFloat = true;
      i++;
      if (text[i] === '+' || text[i] === '-') i++;
