  const parseValue = () => {
    skipWs();
    if (i >= n) error('Expecting value');
    const c = text[i];
    if (c === '{') {
      i++;
      const obj = {};
      skipWs();
      if (text[i] === '}') {
        i++;
        return obj;
      }
      while (true) {
        skipWs();
        if (text[i] !== '"') error('Expecting property name');
        const key = parseString();
        skipWs();
        if (text[i] !== ':') error("Expecting ':' delimiter");
        i++;
        obj[key] = parseValue();
        skipWs();
        if (text[i] === ',') {
          i++;
          continue;
        }
        if (text[i] === '}') {
          i++;
          return obj;
        }
        error("Expecting ',' delimiter");
      }
    }
    if (c === '[') {
      i++;
      const arr = [];
      skipWs();
      if (text[i] === ']') {
        i++;
        return arr;
      }
      while (true) {
        arr.push(parseValue());
        skipWs();
        if (text[i] === ',') {
